def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def lca_bst(tree, p, q):
    node = _build(tree)
    lo, hi = min(p, q), max(p, q)
    while node is not None:
        if hi < node['val']:
            node = node['left']
        elif lo > node['val']:
            node = node['right']
        else:
            return node['val']
    return None
